-- round_of_32 (16) → Round of 32
WITH ranked AS (
  SELECT id, row_number() OVER (ORDER BY match_date, match_code) AS rn
  FROM matches WHERE stage = 'round_of_32'
), csv(rn, ts) AS (VALUES (1, '2026-06-28T15:00:00-04:00'::timestamptz), (2, '2026-06-29T13:00:00-04:00'::timestamptz), (3, '2026-06-29T16:30:00-04:00'::timestamptz), (4, '2026-06-29T21:00:00-04:00'::timestamptz), (5, '2026-06-30T13:00:00-04:00'::timestamptz), (6, '2026-06-30T17:00:00-04:00'::timestamptz), (7, '2026-06-30T21:00:00-04:00'::timestamptz), (8, '2026-07-01T12:00:00-04:00'::timestamptz), (9, '2026-07-01T16:00:00-04:00'::timestamptz), (10, '2026-07-01T20:00:00-04:00'::timestamptz), (11, '2026-07-02T15:00:00-04:00'::timestamptz), (12, '2026-07-02T19:00:00-04:00'::timestamptz), (13, '2026-07-02T23:00:00-04:00'::timestamptz), (14, '2026-07-03T14:00:00-04:00'::timestamptz), (15, '2026-07-03T18:00:00-04:00'::timestamptz), (16, '2026-07-03T21:30:00-04:00'::timestamptz))
UPDATE matches m SET matchday_id = (SELECT id FROM matchdays WHERE wc_stage = 'Round of 32'), match_date = csv.ts
FROM ranked JOIN csv ON csv.rn = ranked.rn WHERE m.id = ranked.id;

