), csv(rn, ts) AS (VALUES (1, '2026-07-04T13:00:00-04:00'::timestamptz), (2, '2026-07-04T17:00:00-04:00'::timestamptz), (3, '2026-07-05T16:00:00-04:00'::timestamptz), (4, '2026-07-05T20:00:00-04:00'::timestamptz), (5, '2026-07-06T15:00:00-04:00'::timestamptz), (6, '2026-07-06T20:00:00-04:00'::timestamptz), (7, '2026-07-07T12:00:00-04:00'::timestamptz), (8, '2026-07-07T16:00:00-04:00'::timestamptz))
UPDATE matches m SET matchday_id = (SELECT id FROM matchdays WHERE wc_stage = 'Round of 16'), match_date = csv.ts
FROM ranked JOIN csv ON csv.rn = ranked.rn WHERE m.id = ranked.id;

-- quarterfinal (4) → Quarter-finals
WITH ranked AS (
  SELECT id, row_number() OVER (ORDER BY match_date, match_code) AS rn
  FROM matches WHERE stage = 'quarterfinal'
), csv(rn, ts) AS (VALUES (1, '2026-07-09T16:00:00-04:00'::timestamptz), (2, '2026-07-10T15:00:00-04:00'::timestamptz), (3, '2026-07-11T17:00:00-04:00'::timestamptz), (4, '2026-07-11T21:00:00-04:00'::timestamptz))
UPDATE matches m SET matchday_id = (SELECT id FROM matchdays WHERE wc_stage = 'Quarter-finals'), match_date = csv.ts
FROM ranked JOIN csv ON csv.rn = ranked.rn WHERE m.id = ranked.id;

-- semifinal (2) — off-season, matchday_id NULL
WITH ranked AS (
  SELECT id, row_number() OVER (ORDER BY match_date, match_code) AS rn
  FROM matches WHERE stage = 'semifinal'
), csv(rn, ts) AS (VALUES (1, '2026-07-14T15:00:00-04:00'::timestamptz), (2, '2026-07-15T15:00:00-04:00'::timestamptz))
UPDATE matches m SET matchday_id = NULL, match_date = csv.ts
FROM ranked JOIN csv ON csv.rn = ranked.rn WHERE m.id = ranked.id;

-- third_place (1) — off-season, matchday_id NULL
WITH ranked AS (
  SELECT id, row_number() OVER (ORDER BY match_date, match_code) AS rn
  FROM matches WHERE stage = 'third_place'
), csv(rn, ts) AS (VALUES (1, '2026-07-18T17:00:00-04:00'::timestamptz))
UPDATE matches m SET matchday_id = NULL, match_date = csv.ts
FROM ranked JOIN csv ON csv.rn = ranked.rn WHERE m.id = ranked.id;

-- final (1) — off-season, matchday_id NULL
WITH ranked AS (
  SELECT id, row_number() OVER (ORDER BY match_date, match_code) AS rn
  FROM matches WHERE stage = 'final'
), csv(rn, ts) AS (VALUES (1, '2026-07-19T15:00:00-04:00'::timestamptz))
UPDATE matches m SET matchday_id = NULL, match_date = csv.ts
FROM ranked JOIN csv ON csv.rn = ranked.rn WHERE m.id = ranked.id;

COMMIT;
